ExtremeValueTheory.IsSubexponential.of_isRegularlyVarying {μ : MeasureTheory.Measure ℝ}
  [MeasureTheory.IsProbabilityMeasure μ] (h0 : μ (Set.Iio 0) = 0) {α : ℝ}
  (hRV : ExtremeValueTheory.IsRegularlyVarying (ExtremeValueTheory.tail μ) (-α)) :
  ExtremeValueTheory.IsSubexponential μ

ExtremeValueTheory.IsSubexponential.convPow {μ : MeasureTheory.Measure ℝ}
  [MeasureTheory.IsProbabilityMeasure μ] (h : ExtremeValueTheory.IsSubexponential μ) {n : ℕ}
  (hn : 1 ≤ n) : ExtremeValueTheory.IsSubexponential (ExtremeValueTheory.Subexp.convPow μ n)

ExtremeValueTheory.IsSubexponential.compound {μ : MeasureTheory.Measure ℝ}
  [MeasureTheory.IsProbabilityMeasure μ] {p : ℕ → NNReal}
  (h : ExtremeValueTheory.IsSubexponential μ) (hp : HasSum p 1) {ε : ℝ} (hε : 0 < ε)
  (hs : Summable fun n => ↑(p n) * (1 + ε) ^ n) (hEN : 0 < ∑' (n : ℕ), ↑n * ↑(p n)) :
  ExtremeValueTheory.IsSubexponential (ExtremeValueTheory.compound μ p)

ExtremeValueTheory.IsSubexponential.tendsto_pkRuin_div {μ : MeasureTheory.Measure ℝ}
  [MeasureTheory.IsProbabilityMeasure μ] (h : ExtremeValueTheory.IsSubexponential μ) {ρ : ℝ}
  (hρ : 0 < ρ) :
  Filter.Tendsto (fun u => ExtremeValueTheory.pkRuin ρ μ u / ExtremeValueTheory.tail μ u)
    Filter.atTop (nhds (1 / ρ))

ExtremeValueTheory.IsSStar.isSubexponential {μ : MeasureTheory.Measure ℝ}
  [MeasureTheory.IsProbabilityMeasure μ] (h : ExtremeValueTheory.IsSStar μ) :
  ExtremeValueTheory.IsSubexponential μ

ExtremeValueTheory.IsSStar.isSubexponential_integratedTail {μ : MeasureTheory.Measure ℝ}
  [MeasureTheory.IsProbabilityMeasure μ] (h : ExtremeValueTheory.IsSStar μ) :
  ExtremeValueTheory.IsSubexponential (ExtremeValueTheory.integratedTail μ)
